import { renderToString } from "react-dom/server";
import { describe, expect, it } from "vitest";
import EntityCommand from "./EntityCommand.js";

describe("EntityCommand SSR", () => {
  it("renders a real link to a homed entity, so it navigates without scripts", () => {
    const html = renderToString(
      <EntityCommand href="#danger" kind="Modifier" title="Danger" />,
    );
    expect(html).toContain("ds entity-command");
    expect(html).toContain('<a class="title" href="#danger">Danger</a>');
  });

  it("renders inert text for an entity without a home", () => {
    const html = renderToString(<EntityCommand title="Danger" />);
    expect(html).toContain('<span class="title">Danger</span>');
    expect(html).not.toContain("<a");
  });
});
